    const generateAI = async () => {
      setGenerating(true)
      const text = transcript || manualText
      const res = await fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${apiKey}`,
        },
        body: JSON.stringify({
          model: 'gpt-3.5-turbo',
          messages: [
            { role: 'system', content: 'you are a helpful assistant' },
            {role:'user', content:`I am attending an interview for a clinical SAS. Please provide moderate and summarized response below 250 words in simple English and should be a latest response from my perspective as a candidate, focusing on ${text}. and please do not give any opening statements or closing statements or any summarized ending or explanatory statement or rationale or justification or concluding statement or lead-ins or During the interview, these type of things`}

            // { role: 'user', content: `${text}` },
          ],
          temperature: 0,
          max_tokens: 200,
          stream: true, // Enable streaming
        }),
      });
    
      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let done = false;
      let accumulatedText = '';
    
      while (!done) {
        const { value, done: readerDone } = await reader.read();
        done = readerDone;
    
        const chunk = decoder.decode(value, { stream: true });
        const lines = chunk.split('\n').filter(line => line.trim() !== '');
    
        for (let line of lines) {
          if (line === '[DONE]') {
            // Stop processing when "[DONE]" is received
            done = true;
            break;
          }
    
          try {
            const json = JSON.parse(line.replace(/^data: /, ''));
            if (json.choices && json.choices[0].delta && json.choices[0].delta.content) {
              const content = json.choices[0].delta.content;
              accumulatedText += content;
              setChatInput(accumulatedText); // Update UI in real-time
      handleSendButton(accumulatedText); // Send full content after streaming is done
              // console.log(content); // Log each chunk
            }
          } catch (error) {
            console.error('Error parsing JSON:', error);
          }
        }
      }
    
      handleSendButton(accumulatedText); // Send full content after streaming is done
      setManualText('')
      setGenerating(false)
    };
    
    
